mapper.select:
SELECT COUNT(1) AS totalStayCount COUNT(CASE WHEN a.status = #{pendingConfirm} THEN 1 ELSE 0 END) AS pendingConfirmCount, COUNT(CASE WHEN a.status = #{pendingAudit} THEN 1 ELSE 0 END) AS pendingAuditCount, COUNT(CASE WHEN a.status = #{passed} THEN 1 ELSE 0 END) AS passedCount FROM stay_mgmt AS a LEFT JOIN student_info AS s ON a.student_id = s.id WHERE a.deleted= 0
AND s.class_name = #{className}
AND stay_date between #{startTime} AND #{endTime}

SELECT DATE_FORMAT(stay_date, '%Y-%m-%d') AS date, COUNT(1) AS count FROM stay_mgmt AS a LEFT JOIN student_info AS s ON a.student_id = s.id WHERE a.deleted= 0
AND s.class_name = #{className}
AND stay_date between #{startTime} AND #{endTime}

SELECT a.status AS status, COUNT(1) AS count FROM stay_mgmt AS a LEFT JOIN student_info AS s ON a.student_id = s.id WHERE a.deleted= 0
AND s.class_name = #{className}
AND stay_date between #{startTime} AND #{endTime}
GROUP BY a.status

SELECT s.class_name AS className, COUNT(1) AS totalCount, COUNT(CASE WHEN a.status = #{pendingConfirm} THEN 1 ELSE 0 END) AS pendingConfirmCount, COUNT(CASE WHEN a.status = #{pendingAudit} THEN 1 ELSE 0 END) AS pendingAuditCount, COUNT(CASE WHEN a.status = #{passed} THEN 1 ELSE 0 END) AS passedCount FROM stay_mgmt AS a LEFT JOIN student_info AS s ON a.student_id = s.id WHERE a.deleted= 0
AND stay_date between #{startTime} AND #{endTime}
GROUP BY class_name
